   130	func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn int, interval, slowDownBackoff time.Duration) (string, error) {
   131		expiry := time.Duration(expiresIn) * time.Second
   132		if expiry <= 0 || expiry > maxExpiresIn {
   133			expiry = maxExpiresIn
   134		}
   135		deadline := time.Now().Add(expiry)
   136		pollInterval := interval
   137		if pollInterval <= 0 {
   138			pollInterval = fallbackDeviceAuthPollInterval
   139		}
   140	
   141		consecutiveErrors := 0
   142	
   143		for {
   144			if time.Now().After(deadline) {
   145				return "", errors.New("device authorization expired")
   146			}
   147	
   148			result, err := poller.PollDeviceAuth(ctx, deviceCode)
   149			if err != nil {
   150				consecutiveErrors++
   151				if consecutiveErrors >= maxTransientErrors {
   152					return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
   153				}
   154				// Transient error — wait and retry.
   155				select {
   156				case <-ctx.Done():
   157					return "", fmt.Errorf("wait for approval: %w", ctx.Err())
   158				case <-time.After(pollInterval):
   159				}
   160				continue
   161			}
   162			consecutiveErrors = 0
   163	
   164			switch result.Error {
   165			case "":
   166				if result.AccessToken == "" {
   167					return "", errors.New("device authorization completed without a token")
   168				}
   169				return result.AccessToken, nil
