   171				// no-op, will sleep and retry below
   172			case "slow_down":
   173				pollInterval += slowDownBackoff
   174				if pollInterval > maxPollInterval {
   175					pollInterval = maxPollInterval
   176				}
   177			case "access_denied":
   178				return "", errors.New("device authorization denied")
   179			case "expired_token":
