    52		coreURL := claims.Issuer
    53		if coreURL == "" {
    54			return "", errors.New("login token has no iss claim; cannot derive core URL for a context")
    55		}
    56		handle := claims.Handle
    57		if handle == "" {
    58			handle = claims.Subject
    59		}
    60		if handle == "" {
    61			return "", errors.New("login token has no handle/sub claim; cannot key the keychain slot")
    62		}
    63	
    64		keychainService := tokenstore.CoreKeyringService(coreURL)
    65	
    66		expiresIn := int64(defaultContextTokenTTL.Seconds())
    67		if !claims.ExpiresAt.IsZero() {
    68			if secs := int64(time.Until(claims.ExpiresAt).Seconds()); secs > 0 {
    69				expiresIn = secs
    70			}
    71		}
    72	
    73		// The refresh token lives in the paired "<service>:refresh" slot (raw,
    74		// no expiry suffix). Clear any prior one when this login carries none,
    75		// so a stale token from an earlier session can't later be replayed
    76		// against the server's single-use rotation and revoke the family.
    77		//
    78		// Write the refresh slot BEFORE the access token, matching
    79		// contextTokenStore.SaveTokens: a partial write must never leave a fresh
    80		// access token paired with a stale refresh token left over from an
    81		// earlier login. Refresh-first means a failed refresh write aborts before
    82		// the access token is touched (old pair preserved), rather than committing
    83		// a new access JWT against a dead refresh token.
    84		refreshSlot := tokenstore.RefreshService(keychainService)
    85		if refreshToken != "" {
    86			if err := tokenstore.Set(refreshSlot, handle, refreshToken); err != nil {
    87				return "", fmt.Errorf("store refresh token in keyring: %w", err)
    88			}
    89		} else {
    90			_ = tokenstore.Delete(refreshSlot, handle) //nolint:errcheck // best-effort cleanup of a stale refresh token
    91		}
    92	
    93		encoded := tokenstore.EncodeTokenWithExpiration(rawToken, expiresIn)
    94		if err := tokenstore.Set(keychainService, handle, encoded); err != nil {
    95			return "", fmt.Errorf("store login token in keyring: %w", err)
    96		}
    97	
    98		var name string
    99		cfgDir := contexts.DefaultConfigDir()
   100		if modErr := contexts.Modify(cfgDir, func(f *contexts.File) (bool, error) {
   101			name = pickContextName(f, coreURL, handle)
   102			f.Upsert(&contexts.Context{
   103				Name:            name,
   104				CoreURL:         coreURL,
   105				Handle:          handle,
   106				KeychainService: keychainService,
   107			})
   108			if activate || f.CurrentContext == "" {
   109				f.CurrentContext = name
   110			}
   111			return true, nil
   112		}); modErr != nil {
   113			return "", fmt.Errorf("write context: %w", modErr)
   114		}
   115	
   116		return name, nil
   117	}
   118	
   119	// pickContextName chooses the contexts.json name for an (coreURL, handle)
   120	// identity within f. An existing context for the same identity keeps its
   121	// name (re-login updates in place). A fresh identity prefers the bare core
   122	// host; if a *different* identity already holds that name, it's qualified
   123	// with the handle (handle@host) so the two don't collide — and, in the
   124	// pathological case that's taken too, a numeric suffix guarantees
   125	// uniqueness.
   126	func pickContextName(f *contexts.File, coreURL, handle string) string {
   127		for _, c := range f.Contexts {
   128			if sameIssuer(c.CoreURL, coreURL) && c.Handle == handle {
   129				return c.Name
   130			}
   131		}
   132		host := contextNameForCoreURL(coreURL)
   133		if f.Find(host) == nil {
   134			return host
   135		}
   136		qualified := handle + "@" + host
   137		if f.Find(qualified) == nil {
   138			return qualified
   139		}
   140		for i := 2; ; i++ {
   141			candidate := fmt.Sprintf("%s-%d", qualified, i)
   142			if f.Find(candidate) == nil {
   143				return candidate
   144			}
   145		}
   146	}
   147	
   148	// sameIssuer compares two core URLs ignoring a trailing slash.
   149	func sameIssuer(a, b string) bool {
   150		return strings.TrimRight(a, "/") == strings.TrimRight(b, "/")
   151	}
   152	
   153	// MigrateLegacyLoginContext bridges users who logged in before the
   154	// contexts.json dual-write existed: if the legacy entire-cli/<authBaseURL>
   155	// keyring entry holds a usable JWT and no context yet covers its issuer,
   156	// it records an equivalent context (and keychain entry under the shared
   157	// scheme) so the git remote helper can authenticate without a re-login.
   158	//
   159	// Returns (true, nil) when it created a context. No-ops — returning
   160	// (false, nil) — when there's no legacy token, the token is opaque
   161	// (no derivable issuer), or a context for that issuer already exists.
   162	// Idempotent: safe to call on every helper invocation.
   163	func MigrateLegacyLoginContext() (migrated bool, err error) {
   164		legacy, err := NewStore().GetToken(api.AuthBaseURL())
   165		if err != nil {
   166			return false, fmt.Errorf("read legacy login token: %w", err)
   167		}
   168		if legacy == "" {
   169			return false, nil
   170		}
   171		claims, parseErr := tokens.ParseClaims(legacy)
   172		if parseErr != nil || claims.Issuer == "" {
   173			// Opaque/unsigned legacy token — can't derive a context from it.
   174			return false, nil //nolint:nilerr // absence of a JWT issuer is not an error here
   175		}
   176		handle := claims.Handle
   177		if handle == "" {
   178			handle = claims.Subject
   179		}
   180		f, err := contexts.Load(contexts.DefaultConfigDir())
   181		if err != nil {
   182			return false, fmt.Errorf("load contexts: %w", err)
   183		}
   184		// Skip only when this exact identity is already represented. Keying on
   185		// issuer alone would skip a legacy bob@core just because alice@core (e.g.
   186		// from another CLI) already exists, leaving Bob without a context.
   187		for _, c := range f.Contexts {
   188			if sameIssuer(c.CoreURL, claims.Issuer) && c.Handle == handle {
   189				return false, nil
   190			}
   191		}
   192		// activate=false: migrating an old login (e.g. on first `git clone`) must
   193		// not silently switch the user's active context. RecordLoginContext still
   194		// sets current_context when none exists yet.
   195		// No refresh token: the legacy entry is access-token-only.
   196		if _, err := RecordLoginContext(legacy, "", false); err != nil {
   197			return false, err
   198		}
   199		return true, nil
   200	}
   201	
   202	// LoginTokenForContext returns the login JWT stored for c, read from the
   203	// OS keyring slot the context points at. The encoded expiry is stripped;
   204	// the server is the authority on validity and the device-flow login holds
   205	// no refresh token, so an expired token surfaces as a 401 the caller can
   206	// translate into a re-login hint.
   207	func LoginTokenForContext(c *contexts.Context) (string, error) {
   208		if c == nil {
   209			return "", errors.New("nil context")
   210		}
   211		if c.KeychainService == "" || c.Handle == "" {
   212			return "", fmt.Errorf("context %q has no keychain slot", c.Name)
   213		}
   214		encoded, err := tokenstore.Get(c.KeychainService, c.Handle)
   215		if err != nil {
   216			return "", fmt.Errorf("read token for context %q: %w", c.Name, err)
   217		}
   218		if encoded == "" {
   219			return "", fmt.Errorf("no token stored for context %q (run `entire login`)", c.Name)
   220		}
   221		token, _ := tokenstore.DecodeTokenWithExpiration(encoded)
   222		return token, nil
   223	}
   224	
   225	// contextNameForCoreURL derives a stable, human-readable context name
   226	// from the issuer URL — its host, matching entiredb's default of naming a
   227	// context after the core it authenticates against. Falls back to the raw
   228	// URL when it can't be parsed.
   229	func contextNameForCoreURL(coreURL string) string {
   230		if u, err := url.Parse(coreURL); err == nil && u.Host != "" {
   231			return u.Host
   232		}
   233		return coreURL
   234	}
